61	/**
62	 * Test some scalable operations related to file renaming and deletion.
63	 * Much of the setup code is lifted from ILoadTestSessionCredentials;
64	 * whereas that was designed to overload an STS endpoint, this just
65	 * tries to overload a single S3 shard with too many bulk IO requests
66	 * -and so see what happens.
67	 * Note: UA field includes the configuration tested for the benefit
68	 * of anyone looking through the server logs.
69	 */
70	@FixMethodOrder(MethodSorters.NAME_ASCENDING)
71	@RunWith(Parameterized.class)
72	public class ILoadTestS3ABulkDeleteThrottling extends S3AScaleTestBase {
73	
74	  private static final Logger LOG =
75	      LoggerFactory.getLogger(ILoadTestS3ABulkDeleteThrottling.class);
76	
77	  protected static final int THREADS = 20;
78	  public static final int TOTAL_KEYS = 25000;
79	
80	  public static final int SMALL = BULK_DELETE_PAGE_SIZE_DEFAULT;
81	  public static final int SMALL_REQS = TOTAL_KEYS / SMALL;
82	
83	  public static final int MAXIMUM = MAX_ENTRIES_TO_DELETE;
84	  public static final int MAXIMUM_REQS = TOTAL_KEYS / MAXIMUM;
85	
86	  // shared across test cases.
87	  @SuppressWarnings("StaticNonFinalField")
88	  private static boolean testWasThrottled;
89	
90	  private final ExecutorService executor =
91	      HadoopExecutors.newFixedThreadPool(
92	          THREADS,
93	          new ThreadFactoryBuilder()
94	              .setNameFormat("#%d")
95	              .build());
96	
97	  private final CompletionService<Outcome>
98	      completionService = new ExecutorCompletionService<>(executor);
99	
100	  private File dataDir;
101	
102	  private final boolean throttle;
103	  private final int pageSize;
104	  private final int requests;
105	
106	  /**
107	   * Test array for parameterized test runs.
108	   * <ul>
109	   *   <li>AWS client throttle on/off</li>
110	   *   <li>Page size</li>
111	   * </ul>
112	   *
113	   * @return a list of parameter tuples.
114	   */
115	  @Parameterized.Parameters(
116	      name = "bulk-delete-aws-retry={0}-requests={2}-size={1}")
117	  public static Collection<Object[]> params() {
118	    return Arrays.asList(new Object[][]{
119	        {false, SMALL, SMALL_REQS},
120	        {false, MAXIMUM, MAXIMUM_REQS},
121	        {true, SMALL, SMALL_REQS},
122	        {true, MAXIMUM, MAXIMUM_REQS},
123	    });
124	  }
125	
126	  /**
127	   * Parameterized constructor.
128	   * @param throttle AWS client throttle on/off
129	   * @param pageSize Page size
130	   * @param requests request count;
131	   */
132	  public ILoadTestS3ABulkDeleteThrottling(
133	      final boolean throttle,
134	      final int pageSize,
135	      final int requests) {
136	    this.throttle = throttle;
137	    Preconditions.checkArgument(pageSize > 0,
138	        "page size too low %s", pageSize);
139	
140	    this.pageSize = pageSize;
141	    this.requests = requests;
142	  }
143	
144	  @Override
145	  protected Configuration createScaleConfiguration() {
146	    Configuration conf = super.createScaleConfiguration();
147	    S3ATestUtils.disableFilesystemCaching(conf);
148	    return conf;
149	  }
150	
151	  @Override
152	  public void setup() throws Exception {
153	    final Configuration conf = getConf();
154	    S3ATestUtils.removeBaseAndBucketOverrides(conf,
155	        EXPERIMENTAL_AWS_INTERNAL_THROTTLING,
156	        BULK_DELETE_PAGE_SIZE,
157	        USER_AGENT_PREFIX);
158	    conf.setBoolean(EXPERIMENTAL_AWS_INTERNAL_THROTTLING, throttle);
159	    Assertions.assertThat(pageSize)
160	        .describedAs("page size")
161	        .isGreaterThan(0);
162	    conf.setInt(BULK_DELETE_PAGE_SIZE, pageSize);
163	    conf.set(USER_AGENT_PREFIX,
164	        String.format("ILoadTestS3ABulkDeleteThrottling-%s-%04d",
165	            throttle, pageSize));
166	
167	    super.setup();
168	    Assume.assumeTrue("multipart delete disabled",
169	        conf.getBoolean(ENABLE_MULTI_DELETE, true));
170	    dataDir = GenericTestUtils.getTestDir("throttling");
171	    dataDir.mkdirs();
172	    final String size = getFileSystem().getConf().get(BULK_DELETE_PAGE_SIZE);
173	    Assertions.assertThat(size)
174	        .describedAs("page size")
175	        .isNotEmpty();
176	    Assertions.assertThat(getFileSystem().getConf()
177	        .getInt(BULK_DELETE_PAGE_SIZE, -1))
178	        .isEqualTo(pageSize);
179	
180	  }
