182	  @Test
183	  public void test_010_Reset() throws Throwable {
184	    testWasThrottled = false;
185	  }
186	
187	  @Test
188	  public void test_020_DeleteThrottling() throws Throwable {
189	    describe("test how S3 reacts to massive multipart deletion requests");
190	    final File results = deleteFiles(requests, pageSize);
191	    LOG.info("Test run completed against {}:\n see {}", getFileSystem(),
192	        results);
193	    if (testWasThrottled) {
194	      LOG.warn("Test was throttled");
195	    } else {
196	      LOG.info("No throttling recorded in filesystem");
197	    }
198	  }
199	
200	  @Test
201	  public void test_030_Sleep() throws Throwable {
202	    maybeSleep();
203	  }
204	
205	  private void maybeSleep() throws InterruptedException, IOException {
206	    if (testWasThrottled) {
207	      LOG.info("Sleeping briefly to let store recover");
208	      Thread.sleep(30_000);
209	      getFileSystem().delete(path("recovery"), true);
210	      testWasThrottled = false;
211	    }
212	  }
213	
214	  /**
215	   * delete files.
216	   * @param requestCount number of requests.
217	   * @throws Exception failure
218	   * @return CSV filename
219	   */
220	  private File deleteFiles(final int requestCount,
221	      final int entries)
222	      throws Exception {
223	    File csvFile = new File(dataDir,
224	        String.format("delete-%03d-%04d-%s.csv",
225	            requestCount, entries, throttle));
226	    describe("Issuing %d requests of size %d, saving log to %s",
227	        requestCount, entries, csvFile);
228	    Path basePath = path("testDeleteObjectThrottling");
229	    final S3AFileSystem fs = getFileSystem();
230	    final String base = fs.pathToKey(basePath);
231	    final List<DeleteObjectsRequest.KeyVersion> fileList
232	        = buildDeleteRequest(base, entries);
233	    final FileWriter out = new FileWriter(csvFile);
234	    Csvout csvout = new Csvout(out, "\t", "\n");
235	    Outcome.writeSchema(csvout);
236	
237	    final ContractTestUtils.NanoTimer jobTimer =
238	        new ContractTestUtils.NanoTimer();
239	
240	    for (int i = 0; i < requestCount; i++) {
241	      final int id = i;
242	      completionService.submit(() -> {
243	        final long startTime = System.currentTimeMillis();
244	        Thread.currentThread().setName("#" + id);
245	        LOG.info("Issuing request {}", id);
246	        final ContractTestUtils.NanoTimer timer =
247	            new ContractTestUtils.NanoTimer();
248	        Exception ex = null;
249	        try {
250	          fs.removeKeys(fileList, false, null);
251	        } catch (IOException e) {
252	          ex = e;
253	        }
254	        timer.end("Request " + id);
255	        return new Outcome(id, startTime, timer,
256	            ex);
257	      });
258	    }
259	
260	    NanoTimerStats stats = new NanoTimerStats("Overall");
261	    NanoTimerStats success = new NanoTimerStats("Successful");
262	    NanoTimerStats throttled = new NanoTimerStats("Throttled");
263	    List<Outcome> throttledEvents = new ArrayList<>();
264	    for (int i = 0; i < requestCount; i++) {
265	      Outcome outcome = completionService.take().get();
266	      ContractTestUtils.NanoTimer timer = outcome.timer;
267	      Exception ex = outcome.exception;
268	      outcome.writeln(csvout);
269	      stats.add(timer);
270	      if (ex != null) {
271	        // throttling event occurred.
272	        LOG.info("Throttled at event {}", i, ex);
273	        throttled.add(timer);
274	        throttledEvents.add(outcome);
275	      } else {
276	        success.add(timer);
277	      }
278	    }
279	
280	    csvout.close();
281	
282	    jobTimer.end("Execution of operations");
283	    // now print the stats
284	    LOG.info("Summary file is " + csvFile);
285	    LOG.info("Made {} requests with {} throttle events\n: {}\n{}\n{}",
286	        requestCount,
287	        throttled.getCount(),
288	        stats,
289	        throttled,
290	        success);
291	
292	    double duration = jobTimer.duration();
293	    double iops = requestCount * entries * 1.0e9 / duration;
294	    LOG.info(String.format("TPS %3f operations/second",
295	        iops));
296	    // log at debug
297	    if (LOG.isDebugEnabled()) {
298	      throttledEvents.forEach((outcome -> {
299	        LOG.debug("{}: duration: {}",
300	            outcome.id, outcome.timer.elapsedTimeMs());
301	      }));
302	    }
303	    return csvFile;
304	  }
305	
306	
307	  private List<DeleteObjectsRequest.KeyVersion> buildDeleteRequest(
308	      String base, int count) {
309	    List<DeleteObjectsRequest.KeyVersion> request = new ArrayList<>(count);
310	    for (int i = 0; i < count; i++) {
311	      request.add(new DeleteObjectsRequest.KeyVersion(
312	          String.format("%s/file-%04d", base, i)));
313	    }
314	    return request;
315	  }
316	
317	  /**
318	   * Outcome of one of the load operations.
319	   */
320	  private static class Outcome {
321	
322	    private final int id;
323	
324	    private final long startTime;
325	
326	    private final ContractTestUtils.NanoTimer timer;
327	
328	    private final Exception exception;
329	
330	    Outcome(final int id,
331	        final long startTime,
332	        final ContractTestUtils.NanoTimer timer,
333	        final Exception exception) {
334	      this.id = id;
335	      this.startTime = startTime;
336	      this.timer = timer;
337	      this.exception = exception;
338	    }
339	
340	    /**
341	     * Write this record.
342	     * @param out the csvout to write through.
343	     * @return the csvout instance
344	     * @throws IOException IO failure.
345	     */
346	    public Csvout writeln(Csvout out) throws IOException {
347	      return out.write(
348	          id,
349	          startTime,
350	          exception == null ? 1 : 0,
351	          timer.getStartTime(),
352	          timer.getEndTime(),
353	          timer.duration(),
354	          '"' + (exception == null ? "" : exception.getMessage()) + '"')
355	          .newline();
356	    }
357	
358	    /**
359	     * Write the schema of the outcome records.
360	     * @param out CSV destinatin
361	     * @throws IOException IO failure.
362	     */
363	    public static void writeSchema(Csvout out) throws IOException {
364	      out.write("id", "starttime", "success", "started", "ended",
365	          "duration", "error").newline();
366	    }
367	  }
368	
369	}

